def remove_zero_sum_pairs(s):
    """反复删除相邻且和为10的数字对。"""
    while True:
        new_s = ""
        i = 0
        while i < len(s):
            if i + 1 < len(s) and int(s[i]) + int(s[i + 1]) == 10:
                i += 2
            else:
                new_s += s[i]
                i += 1
        if new_s == s:
            break
        s = new_s
    return s
