def merge_intervals(intervals):
    """合并重叠或相接的区间。"""
    if not intervals:
        return []

    merged = sorted(intervals, key=lambda x: x[0])
    for i in range(1, len(merged)):
        if merged[i][0] <= merged[i-1][1]:
            merged[i-1][1] = max(merged[i-1][1], merged[i][1])
            merged.pop(i)
            i -= 1

    return merged
