def eval_rpn(tokens):
    """计算逆波兰表达式。"""
    stack = []
    for t in tokens:
        if t in "+-*/":
            b, a = stack.pop(), stack.pop()  # 调整顺序以正确处理减法和除法
            if t == "+":
                stack.append(b + a)
            elif t == "-":
                stack.append(a - b)
            elif t == "*":
                stack.append(b * a)
            else:
                stack.append(a // b)
        else:
            stack.append(int(t))
    return stack[-1]
```

