class LRUCache:
    """最近最少使用缓存。"""

    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}
        self.order = []

    def get(self, key):
        if key in self.data:
            self.order.remove(key)
            self.order.append(key)
            return self.data[key]
        else:
            return -1

    def put(self, key, value):
        if key in self.data:
            self.data[key] = value
            self.order.remove(key)
        elif len(self.data) >= self.capacity:
            old = self.order.pop(0)
            del self.data[old]
        self.data[key] = value
        self.order.append(key)
```

